const categorias = {
  electricidad: 'Electricidad',
  agua: 'Agua',
  gas: 'Gas',
  internet_telefonia: 'Internet y telefonía',
  comunidad: 'Comunidad',
  reparacion_mantenimiento: 'Reparación y mantenimiento',
  honorarios_profesionales: 'Honorarios profesionales',
  seguros: 'Seguros',
  impuestos_tasas: 'Impuestos y tasas',
  otros: 'Otros'
};

const texto = v => {
  if (v && typeof v === 'object') return v.nombre || v.razon_social || '';
  return v ?? '';
};

const mayus = v => v ? v.charAt(0).toUpperCase() + v.slice(1) : '';

return $input.all()
  .map(item => JSON.parse(item.json.output.replace(/```json|```/g, '').trim()))
  .filter(f => f.es_factura !== false)
  .map(f => ({
    json: {
      'Número de factura': texto(f.numero_factura),
      'Fecha de emisión': texto(f.fecha_emision),
      'Fecha de vencimiento': texto(f.fecha_vencimiento),
      'Emisor': texto(f.emisor),
      'Cliente': texto(f.cliente),
      'Inmueble': texto(f.referencia_inmueble),
      'Categoría': categorias[f.categoria_gasto] || mayus(texto(f.categoria_gasto)),
      'Concepto': texto(f.concepto_resumen),
      'Base imponible': f.base_imponible ?? '',
      'Tipo de IVA': f.tipo_iva_pct ?? '',
      'Importe IVA': f.importe_iva ?? '',
      'Retención IRPF': f.retencion_irpf_importe ?? '',
      'Total a pagar': f.total_a_pagar ?? '',
      'Consumo': f.consumo_cantidad ?? '',
      'Unidad': texto(f.consumo_unidad),
      'Estado de pago': mayus(texto(f.estado_pago)),
      'Fecha de pago': texto(f.fecha_pago)
    }
  }));
